/**
 * Workflow-only truth reading engine.
 * 1. Generates ephemeral JSON reading projections from current authoritative files with distributed CSPRNG seeds.
 * 2. Mechanically verifies submitted evidence seed vectors against expected workflow state.
 * 3. Enforces zero mutations on FAIL, atomic cleanup on PASS.
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const REPO_ROOT = path.resolve(__dirname, '../..');
const CATALOG_PATH = path.join(REPO_ROOT, 'truth-reader/catalog.json');
const SELECTOR_PATH = path.join(REPO_ROOT, 'truth-reader/selector.json');
const EVIDENCE_PATH = path.join(REPO_ROOT, 'truth-reader/evidence.json');
const STATUS_PATH = path.join(REPO_ROOT, 'truth-reader/status.json');
const STATE_PATH = path.join(REPO_ROOT, '.github/workflow-state.json');

function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

function writeJson(filePath, data) {
  const dir = path.dirname(filePath);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
  fs.writeFileSync(filePath, JSON.stringify(data, null, 2) + '\n', 'utf8');
}

function generateSeed() {
  return crypto.randomBytes(16).toString('hex');
}

function sha256(value) {
  return crypto.createHash('sha256').update(value, 'utf8').digest('hex');
}

function extractMarkdownRecords(content) {
  const rawChunks = content.split(/\r?\n\r?\n/);
  const records = [];
  let currentTopic = null;
  let recordIndex = 0;

  for (const chunk of rawChunks) {
    const trimmed = chunk.trim();
    if (!trimmed) continue;
    const headingMatch = trimmed.match(/^(#{1,6})\s+(.+)$/m);
    if (headingMatch) {
      currentTopic = headingMatch[2].trim();
    }
    records.push({
      index: recordIndex++,
      topic: currentTopic,
      text: trimmed,
      truth_seed: null
    });
  }

  if (records.length === 0) {
    const lines = content.split(/\r?\n/);
    for (let i = 0; i < lines.length; i++) {
      records.push({
        index: i,
        topic: null,
        text: lines[i],
        truth_seed: null
      });
    }
  }
  return records;
}

function distributeSeedsInTextProjection(records, seeds) {
  const count = records.length;
  if (count === 0) return;

  // Stride-based distribution ensuring broad coverage across start, middle, and end
  const targetSeedCount = Math.max(3, Math.min(count, Math.ceil(count / 4)));
  const step = Math.max(1, Math.floor(count / targetSeedCount));

  for (let i = 0; i < count; i += step) {
    if (records[i]) {
      const seed = generateSeed();
      records[i].truth_seed = seed;
      seeds.push(seed);
    }
  }

  const lastIdx = count - 1;
  if (records[lastIdx] && !records[lastIdx].truth_seed) {
    const seed = generateSeed();
    records[lastIdx].truth_seed = seed;
    seeds.push(seed);
  }
}

function distributeSeedsInJson(sourceValue, seeds) {
  const projection = JSON.parse(JSON.stringify(sourceValue));

  function inject(target) {
    if (Array.isArray(target)) {
      for (let i = 0; i < target.length; i++) {
        if (typeof target[i] === 'object' && target[i] !== null) {
          inject(target[i]);
        } else if (i % 2 === 0) {
          const seed = generateSeed();
          target[i] = { original_value: target[i], truth_seed: seed };
          seeds.push(seed);
        }
      }
    } else if (typeof target === 'object' && target !== null) {
      const keys = Object.keys(target);
      for (const k of keys) {
        if (typeof target[k] === 'object' && target[k] !== null) {
          inject(target[k]);
        }
      }
      const seed = generateSeed();
      target._truth_seed = seed;
      seeds.push(seed);
    }
  }

  inject(projection);
  return projection;
}

function handleGenerate() {
  const catalog = readJson(CATALOG_PATH).documents;
  const selector = readJson(SELECTOR_PATH);

  if (!selector || typeof selector.documents !== 'object' || Array.isArray(selector.documents)) {
    throw new Error('Invalid selector.json structure: documents object required.');
  }

  // Reject arbitrary paths and uncataloged keys
  for (const docKey of Object.keys(selector.documents)) {
    if (!catalog[docKey]) {
      throw new Error(`Rejected unauthorized document key: "${docKey}". Arbitrary paths disallowed.`);
    }
    if (typeof selector.documents[docKey] !== 'boolean') {
      throw new Error(`Rejected non-boolean value for document key: "${docKey}".`);
    }
  }

  const selectedKeys = Object.keys(selector.documents).filter(k => selector.documents[k] === true);
  if (selectedKeys.length === 0) {
    process.stdout.write('No documents selected for truth reading projection generation.\n');
    return { generated: false };
  }

  const orderedSeeds = [];
  const generatedFiles = [];

  for (const docId of selectedKeys) {
    const entry = catalog[docId];
    const fullSourcePath = path.join(REPO_ROOT, entry.sourcePath);
    if (!fs.existsSync(fullSourcePath)) {
      throw new Error(`Authoritative source file not found: ${entry.sourcePath}`);
    }

    const rawContent = fs.readFileSync(fullSourcePath, 'utf8');
    const fullProjectionPath = path.join(REPO_ROOT, entry.projectionPath);
    let projectionData;

    if (entry.type === 'json') {
      const parsed = JSON.parse(rawContent);
      projectionData = distributeSeedsInJson(parsed, orderedSeeds);
    } else {
      const records = extractMarkdownRecords(rawContent);
      distributeSeedsInTextProjection(records, orderedSeeds);
      projectionData = {
        doc_id: docId,
        source_path: entry.sourcePath,
        total_records: records.length,
        records: records
      };
    }

    writeJson(fullProjectionPath, projectionData);
    generatedFiles.push(entry.projectionPath);
  }

  // Workflow-owned expected state: store SHA-256 hashes of the ordered seeds without leaking raw seed plaintext
  const state = {
    active_selection: selectedKeys,
    expected_hashes: orderedSeeds.map(s => sha256(s)),
    seed_count: orderedSeeds.length,
    created_at: new Date().toISOString()
  };
  writeJson(STATE_PATH, state);

  process.stdout.write(`Generated projections for [${selectedKeys.join(', ')}] with ${orderedSeeds.length} distributed seeds.\n`);
  return { generated: true, files: generatedFiles };
}

function handleVerify() {
  if (!fs.existsSync(STATE_PATH)) {
    process.stderr.write('Verification failed: No active expected state found.\n');
    process.exit(1);
  }

  const state = readJson(STATE_PATH);
  const evidence = readJson(EVIDENCE_PATH);

  if (!evidence || !Array.isArray(evidence.seeds) || evidence.seeds.length === 0) {
    process.stderr.write('Verification failed: evidence.json contains no seeds array.\n');
    process.exit(1);
  }

  if (evidence.seeds.length !== state.expected_hashes.length) {
    process.stderr.write(`Verification failed: Expected ${state.expected_hashes.length} seeds, received ${evidence.seeds.length}. Zero mutations performed.\n`);
    process.exit(1);
  }

  for (let i = 0; i < evidence.seeds.length; i++) {
    const submitted = evidence.seeds[i];
    if (typeof submitted !== 'string' || sha256(submitted) !== state.expected_hashes[i]) {
      process.stderr.write(`Verification failed: Seed mismatch at index ${i}. Zero mutations performed.\n`);
      process.exit(1);
    }
  }

  // Exact mechanical match: execute atomic cleanup
  const catalog = readJson(CATALOG_PATH).documents;
  const selector = readJson(SELECTOR_PATH);
  for (const k of Object.keys(selector.documents)) {
    selector.documents[k] = false;
  }
  writeJson(SELECTOR_PATH, selector);

  // Clear evidence seeds
  writeJson(EVIDENCE_PATH, { seeds: [] });

  // Remove generated ephemeral projections
  for (const docId of Object.keys(catalog)) {
    const pPath = path.join(REPO_ROOT, catalog[docId].projectionPath);
    if (fs.existsSync(pPath)) {
      fs.unlinkSync(pPath);
    }
  }

  // Remove internal workflow state
  if (fs.existsSync(STATE_PATH)) {
    fs.unlinkSync(STATE_PATH);
  }

  // Write PASS status
  const status = {
    state: 'PASS',
    verified_at: new Date().toISOString(),
    selected_docs: state.active_selection,
    seed_count: state.seed_count,
    message: 'Exact match verified. Projections, evidence, and selectors atomically reset.'
  };
  writeJson(STATUS_PATH, status);

  process.stdout.write('Verification SUCCESS: Exact match confirmed. Atomic cleanup completed.\n');
}

const mode = process.argv[2];
if (mode === 'generate') {
  handleGenerate();
} else if (mode === 'verify') {
  handleVerify();
} else {
  process.stderr.write(`Unknown mode: ${mode}. Use 'generate' or 'verify'.\n`);
  process.exit(1);
}
